function plain(value) {
  if (value == null) return '';
  if (typeof value === 'object' && !Array.isArray(value) && value.name != null) return String(value.name);
  return String(value);
}

function count(value, fallback = 1) {
  const parsed = Number(plain(value).match(/\d+/)?.[0] ?? fallback);
  return Math.max(1, Math.min(10, Number.isFinite(parsed) ? parsed : fallback));
}

